static boolean check(int x, int y, long num, long k) {
    long t1 = num / x;
    long t2 = num / y;
    long t3 = num / lcm(x, y);
    return t1 + t2 - 2 * t3 >= k;
}

static long lcm(int a, int b) {
    return (long) a * (b / gcd(a, b));
}

static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
